var name = new ArcInlineEdit
{
    Label = "团队名称",
    Value = team.Name,
    Validate = draft => string.IsNullOrWhiteSpace(draft) ? "名称不能为空" : null
};

name.Save += async (_, e) =>
{
    try
    {
        await api.RenameTeamAsync(e.Value);
        team.Name = e.Value;
    }
    catch (Exception exception)
    {
        e.Error = "保存失败：" + exception.Message;
    }
};
